solution.solution.py:
def misses(addresses, lines, line_size):
    cache = []
    count = 0
    for address in addresses:
        block = address // line_size
        if block in cache:
            cache.remove(block)
        else:
            count += 1
            if len(cache) == lines:
                cache.pop(0)
        cache.append(block)
    return count

def grid_misses(rows, cols, by_row):
    if by_row:
        order = [(r * cols + c) * 4 for r in range(rows) for c in range(cols)]
    else:
        order = [(r * cols + c) * 4 for c in range(cols) for r in range(rows)]
    return misses(order, 8, 64)

unitTests:
@test("reading in order: one miss per block")
def _():
    check_eq(misses(list(range(0, 256)), 8, 64), 4)
    check_eq(misses([0, 4, 8, 63, 64], 8, 64), 2)

@test("repeats hit")
def _():
    check_eq(misses([0, 100, 0, 100, 0], 2, 64), 2)

@test("the oldest block is thrown out")
def _():
    # blocks 0, 1, 2 with room for 2: reading block 0 again misses
    check_eq(misses([0, 64, 128, 0], 2, 64), 4)
    # but using block 0 again keeps it fresh
    check_eq(misses([0, 64, 0, 128, 0], 2, 64), 3)

@test("row by row against column by column")
def _():
    check_eq(grid_misses(64, 64, True), 256)
    check_eq(grid_misses(64, 64, False), 4096)

